export interface PricingEquation {
  /**
     * Breakpoint; null = no upper bound
     * @nullable
     */
  upToSqft: number | null;
  basePrice: number;
  /** Base price covers the first N sqft */
  baseSqft: number;
  incrementPrice: number;
  /** Additional price per N sqft, rounded up */
  incrementSqft: number;
  /**
     * Expected labour hours for a job falling in this band. Per band because the work scales with the property — a 4,000 sqft mow is not the same job as a 19,000 sqft one. Null means no estimate for this band, which is deliberately distinct from zero.
     * @nullable
     */
  budgetedHours?: number | null;
  /**
     * Expected cost to deliver a job in this band, for job costing against the rate. Null means no estimate, not zero.
     * @nullable
     */
  budgetedCost?: number | null;
  /**
     * "Never less than": the floor under whatever this band works out to, applied after the base price and every increment. His words on 2026-09-28 were "my starting field on matrix has a min and then from there the Price equation need to take over but I cant set a base" — basePrice used to be both the floor and the number the per-unit equation built from, so a band could not charge per square foot from the first square foot and still refuse to go under the minimum. Null means no floor, which is how every band saved before this existed behaves.
     * @nullable
     */
  minPrice?: number | null;
}

